package com.termux.app.workspace;
import android.app.*;import android.view.*;import android.widget.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.atomic.AtomicReference;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class AgentTimelineSummaryTest {
 Activity activity;AgentChatView view;AtomicReference<JSONObject> opened=new AtomicReference<>();
 @Before public void setup(){activity=Robolectric.buildActivity(Activity.class).setup().get();WorkspaceLanguage.select(activity,"ru");view=new AgentChatView(activity,opened::set,()->{},()->{},()->{},()->{});view.actionCards(true);activity.setContentView(view);}
 @After public void close(){activity.finish();}
 List<JSONObject> source(String agent)throws Exception{try(InputStream in=getClass().getResourceAsStream("/timeline-adapter-events.json")){assertNotNull(in);ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))>=0)bytes.write(b,0,n);JSONArray a=new JSONObject(bytes.toString("UTF-8")).getJSONArray(agent);List<JSONObject> out=new ArrayList<>();for(int i=0;i<a.length();i++)out.add(a.getJSONObject(i));return out;}}
 CodexActionsView card(){return(CodexActionsView)view.timeline.getChildAt(1);}
 void layout(){for(int i=0;i<3;i++){view.measure(View.MeasureSpec.makeMeasureSpec(320,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(500,View.MeasureSpec.EXACTLY));view.layout(0,0,320,500);Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();}}
 void adapter(String agent)throws Exception{for(String lang:new String[]{"ru","en"}){WorkspaceLanguage.select(activity,lang);view.clear();List<JSONObject> rows=source(agent);String nativeJson=rows.toString();view.rows(rows,true);CodexActionsView c=card();assertEquals(View.GONE,c.steps.getVisibility());assertTrue(c.heading.getText().toString().contains("8"));String summary=c.summary.getText().toString();assertTrue(summary,summary.contains(lang.equals("ru")?"Чтение: 1":"Reads: 1"));assertTrue(summary,summary.contains(lang.equals("ru")?"Правки: 1":"Edits: 1"));assertTrue(summary,summary.contains(lang.equals("ru")?"Команды: 5":"Commands: 5"));assertTrue(summary,summary.contains(lang.equals("ru")?"Другие: 1":"Other: 1"));assertEquals(8,c.steps.getChildCount());c.summaryCard.performClick();assertEquals(View.VISIBLE,c.steps.getVisibility());
  boolean declined=false,bad=false,retry=false,unknown=false;for(int i=0;i<8;i++){TextView item=(TextView)c.steps.getChildAt(i);String text=item.getText().toString();assertFalse(text,text.contains("ONLY_TEST_TIMELINE"));assertFalse(text,text.contains("/synthetic/"));assertNull(item.getEllipsize());assertEquals(Integer.MAX_VALUE,item.getMaxLines());item.performClick();JSONObject row=opened.get();assertNotNull(row);assertEquals("tool",row.optString("kind"));assertFalse(row.optString("message").isEmpty());assertFalse(row.optString("part").isEmpty());assertTrue("Details retain the original payload",row.optString("body").contains("ONLY_TEST_TIMELINE")||AgentTimelineSummary.kind(row)==AgentTimelineSummary.Kind.READ||AgentTimelineSummary.kind(row)==AgentTimelineSummary.Kind.EDIT||AgentTimelineSummary.kind(row)==AgentTimelineSummary.Kind.OTHER);
   if(AgentActionPresentation.userDeclined(row)){declined=true;assertEquals(0xfff0f0ee,item.getCurrentTextColor());assertTrue(text,text.contains(lang.equals("ru")?"Действие отклонено":"Action declined"));}
   if(row.optString("command").contains("fixture-bad")){bad=true;assertEquals(0xffffb08f,item.getCurrentTextColor());assertTrue(CodexActionTimeline.failed(row));}
   if(row.optString("command").contains("fixture-retry")){retry=true;assertFalse(CodexActionTimeline.failed(row));assertFalse(text.contains("проверка пройдена"));}
   if(row.optString("toolName").equals("unrelated.Read")){unknown=true;assertTrue(text.contains("unrelated.Read"));assertTrue(text.contains(lang.equals("ru")?"Тип не определён":"Type unspecified"));}
  }assertTrue(declined);assertTrue(unknown);assertTrue("Failed and retried actions remain separately visible",bad&&retry);assertTrue(c.outcomes.getText().toString().toLowerCase(java.util.Locale.ROOT).contains(lang.equals("ru")?"ошибкой":"failed"));assertEquals(nativeJson,rows.toString());view.rows(rows,true);assertSame(c,card());assertEquals(View.VISIBLE,c.steps.getVisibility());c.summaryCard.performClick();view.rows(source(agent),true);assertEquals(View.GONE,card().steps.getVisibility());assertEquals(View.VISIBLE,view.older.getVisibility());
 }}
 @Test public void codexActualProjectionAndColdReopen()throws Exception{adapter("codex");}
 @Test public void claudeActualProjectionCountsCallAndResultOnce()throws Exception{adapter("claude");}
 @Test public void geminiActualProjectionAndColdReopen()throws Exception{adapter("gemini");}
 @Test public void openCodeActualProjectionAndColdReopen()throws Exception{adapter("opencode");}
 JSONObject row(String key,String status)throws Exception{return new JSONObject().put("key",key).put("kind","tool").put("actionType","shell").put("command","fixture "+key).put("status",status).put("body","original output");}
 @Test public void olderPageAndCacheReopenKeepExplicitChoiceAndDoNotMixChats()throws Exception{
  JSONObject a=row("a","running"),b=row("b","completed"),old=row("older","completed");view.rows(Arrays.asList(a,b),true);CodexActionsView c=card();c.summaryCard.performClick();view.olderRows(Arrays.asList(old,a,b),false);assertEquals(View.VISIBLE,card().steps.getVisibility());card().summaryCard.performClick();view.olderRows(Arrays.asList(row("oldest","completed"),old,a,b),false);assertEquals(View.GONE,card().steps.getVisibility());
  AgentChatCache.State saved=new AgentChatCache.State();saved.timelineExpansion.putAll(view.timelineExpansion);saved.rows.put("a",a);saved.rows.put("b",b);AgentChatCache cache=new AgentChatCache();cache.put("chat-A",saved);view.clear();view.rows(Arrays.asList(a,b),false);assertTrue(view.timelineExpansion.isEmpty());assertEquals(View.GONE,card().steps.getVisibility());saved=cache.take("chat-A");view.clear();view.timelineExpansion.putAll(saved.timelineExpansion);view.rows(new ArrayList<>(saved.rows.values()),false);assertEquals(View.GONE,card().steps.getVisibility());card().summaryCard.performClick();assertEquals(View.VISIBLE,card().steps.getVisibility());
  for(int i=0;i<1500;i++)view.rememberActions(Collections.singletonList(row("k"+i,"completed")),false);assertEquals(1024,view.timelineExpansion.size());
 }
 @Test public void runningChangeAboveReadingActionRetainsNestedAnchor()throws Exception{
  List<JSONObject> rows=new ArrayList<>();for(int i=0;i<24;i++)rows.add(row("r"+i,i==0?"running":"completed"));view.rows(rows,true);card().summaryCard.performClick();layout();CodexActionsView c=card();int target=c.getTop()+c.stepTop("r12");view.scroll.scrollTo(0,target);int offset=view.position().offset;assertEquals("r12",view.position().step);
  rows.get(0).put("command","first line\nprivate output").put("status","awaiting_approval");view.rows(rows,true);layout();assertEquals("r12",view.position().step);assertEquals(offset,view.position().offset);assertEquals(View.VISIBLE,card().steps.getVisibility());
  List<JSONObject> older=new ArrayList<>();older.add(row("prepend","completed"));older.addAll(rows);view.olderRows(older,false);layout();assertEquals("r12",view.position().step);assertEquals(offset,view.position().offset);
 }

 @Test public void collapsedNewEventsStayCollapsedAndFollowOnlyAtTheBottom()throws Exception{
  List<JSONObject> rows=new ArrayList<>();for(int i=0;i<25;i++)rows.add(new JSONObject().put("key","m"+i).put("kind","text").put("body","Synthetic message "+i+"\nsecond line\nthird line"));JSONObject running=row("active","running");rows.add(running);view.rows(rows,true);layout();view.scroll.scrollTo(0,view.timeline.getHeight());assertTrue(view.position().bottom);CodexActionsView c=(CodexActionsView)view.timeline.getChildAt(view.timeline.getChildCount()-3);assertEquals(View.GONE,c.steps.getVisibility());
  rows.add(row("next","running"));view.rows(rows,true);layout();assertEquals(View.GONE,c.steps.getVisibility());assertTrue("New action follows when already at bottom",view.position().bottom);
  view.scroll.scrollTo(0,200);AgentChatView.Position before=view.position();assertFalse(before.bottom);running.put("status","completed");rows.add(new JSONObject().put("key","answer").put("kind","text").put("body","New synthetic answer\nmore content"));view.rows(rows,true);layout();assertEquals(before.anchor,view.position().anchor);assertEquals(before.offset,view.position().offset);assertEquals(View.GONE,c.steps.getVisibility());
  view.scroll.scrollTo(0,view.timeline.getHeight());rows.get(rows.size()-1).put("body","New synthetic answer\nmore content\nextra line\nlast line");view.rows(rows,true);layout();assertTrue("New answer follows when at bottom",view.position().bottom);
 }
 @Test public void noInferredTypesDurationsOrTestSuccessAndExplicitCancelRemainsDistinct()throws Exception{
  JSONObject unknown=row("custom","completed").put("toolName","custom.Read");unknown.remove("actionType");assertEquals(AgentTimelineSummary.Kind.OTHER,AgentTimelineSummary.kind(unknown));assertEquals("custom.Read",AgentTimelineSummary.title(unknown,true));JSONObject shell=row("shell","completed").put("eventTime",1793870400000L).put("exitCode",0);assertFalse(AgentActionPresentation.state(shell,true).contains("мс"));assertFalse(AgentActionPresentation.state(shell,true).contains("провер"));assertEquals(0,AgentTimelineSummary.start(shell));assertEquals("Отменено",AgentActionPresentation.state(row("cancel","cancelled"),true));assertEquals("Прервано",AgentActionPresentation.state(row("abort","aborted"),true));assertFalse(AgentTimelineSummary.neutral(row("abort","aborted")));assertTrue(AgentTimelineSummary.neutral(row("cancel","cancelled")));
 }
 @Test public void largeTextAndLongNamesKeepDetailsAndFullMultilineLabels()throws Exception{
  for(int width:new int[]{240,320}){view.clear();List<JSONObject> rows=source("opencode");view.rows(rows,false);card().summaryCard.performClick();view.scale(150);view.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1500,View.MeasureSpec.EXACTLY));view.layout(0,0,width,1500);CodexActionsView c=card();assertTrue(c.heading.getWidth()>0);assertTrue(c.heading.getRight()<=c.time.getLeft()||c.time.getVisibility()==View.GONE);TextView item=(TextView)c.steps.getChildAt(0);assertNull(item.getEllipsize());assertTrue(item.getLayout().getHeight()+item.getTotalPaddingTop()+item.getTotalPaddingBottom()<=item.getHeight());item.performClick();assertTrue(AgentTimelineSummary.path(opened.get()).length()>100);}
 }
}
